-- AU commercial documents. No physical movement, time source or invoice is
-- created by saving a commercial plan. Paid execution remains at a separate SA.
CREATE TABLE sd_org_units(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,organization_id uuid NOT NULL,company_id uuid,kind text NOT NULL CHECK(kind IN('SALES_ORG','CHANNEL','DIVISION')),code text NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK((kind='SALES_ORG')=(company_id IS NOT NULL)),UNIQUE(tenant_id,id),UNIQUE(tenant_id,organization_id,kind,code),
 FOREIGN KEY(tenant_id,organization_id) REFERENCES organizations(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES company_codes(tenant_id,id)
);
CREATE TABLE sd_sales_areas(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,organization_id uuid NOT NULL,sales_org_id uuid NOT NULL,channel_id uuid NOT NULL,division_id uuid NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1 CHECK(version>0),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,sales_org_id,channel_id,division_id),
 FOREIGN KEY(tenant_id,organization_id) REFERENCES organizations(tenant_id,id),FOREIGN KEY(tenant_id,sales_org_id) REFERENCES sd_org_units(tenant_id,id),FOREIGN KEY(tenant_id,channel_id) REFERENCES sd_org_units(tenant_id,id),FOREIGN KEY(tenant_id,division_id) REFERENCES sd_org_units(tenant_id,id)
);
CREATE TABLE sd_terms(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,organization_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('PAYMENT','SHIPPING','INCOTERMS')),code text NOT NULL,name text NOT NULL,net_days integer,edition text,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK((kind='PAYMENT')=(net_days IS NOT NULL)),CHECK(net_days IS NULL OR net_days BETWEEN 0 AND 365),CHECK((kind='INCOTERMS')=(edition IS NOT NULL)),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,organization_id,kind,code),FOREIGN KEY(tenant_id,organization_id) REFERENCES organizations(tenant_id,id)
);
CREATE TABLE sales_orders(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,organization_id uuid NOT NULL,company_id uuid NOT NULL,sales_area_id uuid NOT NULL,partner_id uuid NOT NULL,title text NOT NULL,kind text NOT NULL CHECK(kind IN('STANDARD','PROJECT','REPAIR')),currency text NOT NULL,order_date date NOT NULL,pricing_date date NOT NULL,customer_reference text NOT NULL DEFAULT '',customer_reference_date date,requested_on date,payment_term_id uuid,shipping_term_id uuid,incoterm_id uuid,incoterm_place text NOT NULL DEFAULT '',responsible_id uuid,delivery_block text,billing_block text,header_text text NOT NULL DEFAULT '',internal_text text NOT NULL DEFAULT '',
 status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','IN_REVIEW','RELEASED','REJECTED','CANCELLED')),version integer NOT NULL DEFAULT 1 CHECK(version>0),data_revision integer NOT NULL DEFAULT 1 CHECK(data_revision>0),approval_snapshot jsonb,released_snapshot jsonb,released_at timestamptz,released_by uuid,confirmation_number text,cancel_reason text,
 CHECK(delivery_block IS NULL OR length(delivery_block)>=5),CHECK(billing_block IS NULL OR length(billing_block)>=5),CHECK((status='CANCELLED')=(cancel_reason IS NOT NULL)),CHECK(cancel_reason IS NULL OR length(cancel_reason)>=15),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,confirmation_number),FOREIGN KEY(tenant_id,id) REFERENCES documents(tenant_id,id),FOREIGN KEY(tenant_id,organization_id) REFERENCES organizations(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES company_codes(tenant_id,id),FOREIGN KEY(tenant_id,sales_area_id) REFERENCES sd_sales_areas(tenant_id,id),FOREIGN KEY(tenant_id,partner_id) REFERENCES business_partners(tenant_id,id),FOREIGN KEY(tenant_id,currency) REFERENCES currencies(tenant_id,code),FOREIGN KEY(tenant_id,payment_term_id) REFERENCES sd_terms(tenant_id,id),FOREIGN KEY(tenant_id,shipping_term_id) REFERENCES sd_terms(tenant_id,id),FOREIGN KEY(tenant_id,incoterm_id) REFERENCES sd_terms(tenant_id,id),FOREIGN KEY(tenant_id,responsible_id) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,released_by) REFERENCES users(tenant_id,id)
);
CREATE TABLE sales_order_partners(
 tenant_id uuid NOT NULL,order_id uuid NOT NULL,role text NOT NULL CHECK(role IN('SOLD_TO','SHIP_TO','BILL_TO','PAYER')),partner_id uuid NOT NULL,address_id uuid NOT NULL,contact_id uuid,override_reason text NOT NULL DEFAULT '',
 PRIMARY KEY(tenant_id,order_id,role),FOREIGN KEY(tenant_id,order_id) REFERENCES sales_orders(tenant_id,id),FOREIGN KEY(tenant_id,partner_id) REFERENCES business_partners(tenant_id,id),FOREIGN KEY(tenant_id,address_id) REFERENCES partner_addresses(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES partner_contacts(tenant_id,id)
);
CREATE TABLE sales_order_items(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,order_id uuid NOT NULL,position integer NOT NULL CHECK(position>0),parent_item_id uuid,product_id uuid NOT NULL,item_category text NOT NULL CHECK(item_category IN('STANDARD','NON_BILLABLE')),customer_material text NOT NULL DEFAULT '',description text NOT NULL,quantity numeric(18,6) NOT NULL CHECK(quantity>0),unit text NOT NULL,billing_rule text NOT NULL CHECK(billing_rule IN('TIME_MATERIAL','FIXED_PRICE','NON_BILLABLE')),cost_center text NOT NULL DEFAULT '',cost_object text NOT NULL DEFAULT '',profit_center text NOT NULL DEFAULT '',project_reference text NOT NULL DEFAULT '',requested_on date,delivery_block text,billing_block text,rejection_reason text,item_text text NOT NULL DEFAULT '',product_snapshot jsonb NOT NULL,price_snapshot jsonb NOT NULL,net numeric(20,4) NOT NULL CHECK(net>=0),tax numeric(20,4) NOT NULL CHECK(tax>=0),gross numeric(20,4) NOT NULL CHECK(gross=net+tax),
 CHECK(parent_item_id IS DISTINCT FROM id),CHECK((item_category='NON_BILLABLE')=(billing_rule='NON_BILLABLE')),CHECK(rejection_reason IS NULL OR length(rejection_reason)>=5),CHECK(delivery_block IS NULL OR length(delivery_block)>=5),CHECK(billing_block IS NULL OR length(billing_block)>=5),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,order_id,position),FOREIGN KEY(tenant_id,order_id) REFERENCES sales_orders(tenant_id,id),FOREIGN KEY(tenant_id,parent_item_id) REFERENCES sales_order_items(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id)
);
CREATE TABLE sales_order_schedules(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,order_id uuid NOT NULL,item_id uuid NOT NULL,position integer NOT NULL CHECK(position>0),quantity numeric(18,6) NOT NULL CHECK(quantity>0),requested_on date NOT NULL,confirmed_on date,
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,item_id,position),FOREIGN KEY(tenant_id,order_id) REFERENCES sales_orders(tenant_id,id),FOREIGN KEY(tenant_id,item_id) REFERENCES sales_order_items(tenant_id,id)
);
CREATE TABLE sales_order_events(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,order_id uuid NOT NULL,revision integer NOT NULL,kind text NOT NULL,actor_id uuid NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),snapshot jsonb NOT NULL,
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,order_id,revision),FOREIGN KEY(tenant_id,order_id) REFERENCES sales_orders(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id)
);
CREATE TRIGGER sales_order_event_immutable BEFORE UPDATE OR DELETE ON sales_order_events FOR EACH ROW EXECUTE FUNCTION reject_attachment_mutation();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['sd_org_units','sd_sales_areas','sd_terms','sales_orders','sales_order_partners','sales_order_items','sales_order_schedules','sales_order_events'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);
END LOOP;END$$;
CREATE FUNCTION sd_structure_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE org uuid;BEGIN
 IF TG_TABLE_NAME='sd_org_units' AND (to_jsonb(NEW)->>'kind')='SALES_ORG' THEN
  SELECT organization_id INTO STRICT org FROM company_codes WHERE tenant_id=NEW.tenant_id AND id=NEW.company_id;IF org<>NEW.organization_id THEN RAISE EXCEPTION 'Verkaufsorganisation und Buchungskreis gehören nicht zusammen';END IF;
 ELSIF TG_TABLE_NAME='sd_sales_areas' THEN
  IF NOT EXISTS(SELECT 1 FROM sd_org_units s JOIN sd_org_units ch ON ch.tenant_id=s.tenant_id AND ch.organization_id=s.organization_id JOIN sd_org_units di ON di.tenant_id=s.tenant_id AND di.organization_id=s.organization_id WHERE s.tenant_id=NEW.tenant_id AND s.id=NEW.sales_org_id AND s.kind='SALES_ORG' AND s.organization_id=NEW.organization_id AND ch.id=NEW.channel_id AND ch.kind='CHANNEL' AND di.id=NEW.division_id AND di.kind='DIVISION') THEN RAISE EXCEPTION 'Vertriebsbereich benötigt passende Verkaufsorganisation, Vertriebsweg und Sparte';END IF;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.version<>OLD.version+1 OR (to_jsonb(OLD)-'name'-'active'-'version') IS DISTINCT FROM (to_jsonb(NEW)-'name'-'active'-'version') THEN RAISE EXCEPTION 'SD-Stammidentität bleibt erhalten; neue Revision für Bezeichnung/Aktivität erforderlich';END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER sd_unit_structure BEFORE INSERT OR UPDATE ON sd_org_units FOR EACH ROW EXECUTE FUNCTION sd_structure_guard();
CREATE TRIGGER sd_area_structure BEFORE INSERT OR UPDATE ON sd_sales_areas FOR EACH ROW EXECUTE FUNCTION sd_structure_guard();
CREATE TRIGGER sd_terms_structure BEFORE INSERT OR UPDATE ON sd_terms FOR EACH ROW EXECUTE FUNCTION sd_structure_guard();
CREATE FUNCTION sales_order_header_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE area_company uuid;area_org uuid;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'AU bleibt erhalten; begründeter Abbruch bzw. Folgevorgang erforderlich';END IF;
 SELECT s.company_id,a.organization_id INTO STRICT area_company,area_org FROM sd_sales_areas a JOIN sd_org_units s ON s.tenant_id=a.tenant_id AND s.id=a.sales_org_id WHERE a.tenant_id=NEW.tenant_id AND a.id=NEW.sales_area_id;
 IF area_company<>NEW.company_id OR area_org<>NEW.organization_id OR NOT EXISTS(SELECT 1 FROM documents d JOIN business_partners p ON p.tenant_id=d.tenant_id AND p.organization_id=d.organization_id WHERE d.tenant_id=NEW.tenant_id AND d.id=NEW.id AND d.kind='SALES_ORDER' AND d.organization_id=NEW.organization_id AND p.id=NEW.partner_id AND 'CUSTOMER'=ANY(p.roles)) THEN RAISE EXCEPTION 'AU gehört nicht zu diesem Vertriebsbereich, Buchungskreis oder Kunden';END IF;
 IF TG_OP='INSERT' THEN IF NEW.status<>'DRAFT' OR NEW.confirmation_number IS NOT NULL OR NEW.released_snapshot IS NOT NULL OR NEW.released_at IS NOT NULL OR NEW.released_by IS NOT NULL THEN RAISE EXCEPTION 'AU beginnt als kommerzieller Entwurf';END IF;RETURN NEW;END IF;
 IF OLD.status IN('RELEASED','CANCELLED') THEN RAISE EXCEPTION 'Freigegebener oder abgebrochener AU bleibt unveränderlich';END IF;
 IF (OLD.id,OLD.tenant_id,OLD.organization_id,OLD.company_id,OLD.sales_area_id,OLD.partner_id,OLD.currency,OLD.kind,OLD.order_date) IS DISTINCT FROM (NEW.id,NEW.tenant_id,NEW.organization_id,NEW.company_id,NEW.sales_area_id,NEW.partner_id,NEW.currency,NEW.kind,NEW.order_date) THEN RAISE EXCEPTION 'AU-Identität bleibt unveränderlich';END IF;
 IF NEW.version<OLD.version OR NEW.version>OLD.version+1 OR NEW.data_revision<OLD.data_revision OR NEW.data_revision>OLD.data_revision+1 OR (NEW.data_revision<>OLD.data_revision AND NEW.version<>OLD.version+1) THEN RAISE EXCEPTION 'AU-Version darf nicht zurückgesetzt oder übersprungen werden';END IF;
 IF NEW.status<>OLD.status AND NOT ((OLD.status IN('DRAFT','REJECTED') AND NEW.status IN('DRAFT','IN_REVIEW','CANCELLED')) OR (OLD.status='IN_REVIEW' AND NEW.status IN('DRAFT','RELEASED','REJECTED'))) THEN RAISE EXCEPTION 'Unzulässiger AU-Statusübergang';END IF;
 IF OLD.status='IN_REVIEW' AND (to_jsonb(OLD)-'status'-'version'-'released_snapshot'-'released_at'-'released_by'-'confirmation_number') IS DISTINCT FROM (to_jsonb(NEW)-'status'-'version'-'released_snapshot'-'released_at'-'released_by'-'confirmation_number') THEN RAISE EXCEPTION 'AU-Prüfstand ist während Freigabe gebunden';END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER sales_order_header_frozen BEFORE INSERT OR UPDATE OR DELETE ON sales_orders FOR EACH ROW EXECUTE FUNCTION sales_order_header_guard();
CREATE FUNCTION sales_order_child_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE h sales_orders;row_data jsonb;parent sales_order_items;role_partner business_partners;role_address partner_addresses;role_contact partner_contacts;BEGIN
 row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;SELECT * INTO STRICT h FROM sales_orders WHERE tenant_id=(row_data->>'tenant_id')::uuid AND id=(row_data->>'order_id')::uuid;
 IF h.status NOT IN('DRAFT','REJECTED') THEN RAISE EXCEPTION 'AU-Positionen und Partner sind in Prüfung oder nach Freigabe gebunden';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 IF TG_TABLE_NAME='sales_order_partners' THEN
  SELECT * INTO STRICT role_partner FROM business_partners WHERE tenant_id=NEW.tenant_id AND id=NEW.partner_id;SELECT * INTO STRICT role_address FROM partner_addresses WHERE tenant_id=NEW.tenant_id AND id=NEW.address_id;
  IF role_partner.organization_id<>h.organization_id OR NOT 'CUSTOMER'=ANY(role_partner.roles) OR role_address.partner_id<>role_partner.id OR (NEW.role='SOLD_TO' AND role_partner.id<>h.partner_id) OR (NEW.partner_id<>h.partner_id AND length(NEW.override_reason)<15) THEN RAISE EXCEPTION 'AU-Partnerrolle, Adresse oder begründete Übersteuerung stimmt nicht';END IF;
  IF NEW.contact_id IS NOT NULL THEN SELECT * INTO STRICT role_contact FROM partner_contacts WHERE tenant_id=NEW.tenant_id AND id=NEW.contact_id;IF role_contact.partner_id<>role_partner.id THEN RAISE EXCEPTION 'Ansprechpartner gehört nicht zum Rollenpartner';END IF;END IF;
 ELSIF TG_TABLE_NAME='sales_order_items' THEN
  IF NOT EXISTS(SELECT 1 FROM products p JOIN documents d ON d.tenant_id=p.tenant_id AND d.id=p.id WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.product_id AND d.organization_id=h.organization_id AND p.unit=NEW.unit) THEN RAISE EXCEPTION 'AU-Artikel und Einheit gehören nicht zur Organisation';END IF;
  IF NEW.parent_item_id IS NOT NULL THEN SELECT * INTO STRICT parent FROM sales_order_items WHERE tenant_id=NEW.tenant_id AND id=NEW.parent_item_id;IF parent.order_id<>h.id OR parent.position>=NEW.position THEN RAISE EXCEPTION 'Überposition muss frühere Position desselben AU sein';END IF;END IF;
 ELSIF TG_TABLE_NAME='sales_order_schedules' THEN
  IF NOT EXISTS(SELECT 1 FROM sales_order_items i WHERE i.tenant_id=NEW.tenant_id AND i.id=NEW.item_id AND i.order_id=h.id) THEN RAISE EXCEPTION 'Einteilung gehört nicht zur AU-Position';END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER sales_order_partner_source BEFORE INSERT OR UPDATE OR DELETE ON sales_order_partners FOR EACH ROW EXECUTE FUNCTION sales_order_child_guard();
CREATE TRIGGER sales_order_item_source BEFORE INSERT OR UPDATE OR DELETE ON sales_order_items FOR EACH ROW EXECUTE FUNCTION sales_order_child_guard();
CREATE TRIGGER sales_order_schedule_source BEFORE INSERT OR UPDATE OR DELETE ON sales_order_schedules FOR EACH ROW EXECUTE FUNCTION sales_order_child_guard();
CREATE FUNCTION sales_order_event_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE current_order sales_orders;BEGIN
 SELECT * INTO STRICT current_order FROM sales_orders WHERE tenant_id=NEW.tenant_id AND id=NEW.order_id;
 IF current_order.status NOT IN('DRAFT','REJECTED') OR current_order.data_revision<>NEW.revision OR NOT EXISTS(SELECT 1 FROM users usr JOIN user_organizations o ON o.tenant_id=usr.tenant_id AND o.user_id=usr.id WHERE usr.tenant_id=NEW.tenant_id AND usr.id=NEW.actor_id AND usr.active AND usr.role IN('ADMIN','SERVICE_MANAGER','SALES') AND o.organization_id=current_order.organization_id) THEN RAISE EXCEPTION 'AU-Änderung benötigt aktuelle Datenrevision und berechtigten Bearbeiter';END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER sales_order_event_source BEFORE INSERT ON sales_order_events FOR EACH ROW EXECUTE FUNCTION sales_order_event_guard();
CREATE FUNCTION sales_order_release_consistent() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE current_order sales_orders;creator uuid;BEGIN
 SELECT * INTO STRICT current_order FROM sales_orders WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 IF NOT EXISTS(SELECT 1 FROM sales_order_events ev WHERE ev.tenant_id=current_order.tenant_id AND ev.order_id=current_order.id AND ev.revision=current_order.data_revision) THEN RAISE EXCEPTION 'Tatsächlicher AU-Änderungsverlauf fehlt';END IF;
 IF current_order.status<>'RELEASED' THEN
  IF current_order.confirmation_number IS NOT NULL OR current_order.released_snapshot IS NOT NULL OR current_order.released_at IS NOT NULL OR current_order.released_by IS NOT NULL THEN RAISE EXCEPTION 'Unvollständige AU-Freigabe darf keinen freigegebenen Originalstand vortäuschen';END IF;RETURN NULL;
 END IF;
 SELECT created_by INTO STRICT creator FROM documents WHERE tenant_id=current_order.tenant_id AND id=current_order.id;
 IF current_order.confirmation_number IS NULL OR current_order.confirmation_number!~'^AB-43[0-9]{6}$' OR current_order.released_snapshot->>'confirmationNumber' IS DISTINCT FROM current_order.confirmation_number OR current_order.approval_snapshot IS NULL OR current_order.released_snapshot->'commercial' IS DISTINCT FROM current_order.approval_snapshot OR current_order.released_by IS NULL OR current_order.released_at IS NULL OR current_order.released_snapshot->'review'->>'actorId' IS DISTINCT FROM current_order.released_by::text OR (current_order.released_snapshot->'review'->>'at')::timestamptz IS DISTINCT FROM current_order.released_at OR length(current_order.released_snapshot->'review'->>'note')<15 THEN RAISE EXCEPTION 'Gebundener vollständiger AU-Freigabestand fehlt';END IF;
 IF current_order.released_by=creator OR EXISTS(SELECT 1 FROM sales_order_events ev WHERE ev.tenant_id=current_order.tenant_id AND ev.order_id=current_order.id AND ev.actor_id=current_order.released_by) OR NOT EXISTS(SELECT 1 FROM users usr JOIN user_organizations o ON o.tenant_id=usr.tenant_id AND o.user_id=usr.id WHERE usr.tenant_id=current_order.tenant_id AND usr.id=current_order.released_by AND usr.active AND usr.role IN('ADMIN','SERVICE_MANAGER','SALES','EXECUTIVE') AND o.organization_id=current_order.organization_id) THEN RAISE EXCEPTION 'AU-Bearbeiter darf eigenen Stand nicht freigeben; aktive unabhängige Vertriebsprüfung erforderlich';END IF;
 IF NOT EXISTS(SELECT 1 FROM approval_instances ai JOIN approval_decisions ad ON ad.tenant_id=ai.tenant_id AND ad.instance_id=ai.id WHERE ai.tenant_id=current_order.tenant_id AND ai.document_id=current_order.id AND ai.status='APPROVED' AND ai.four_eyes AND ai.submitted_by<>current_order.released_by AND ad.actor_id=current_order.released_by AND ad.decision='APPROVE' AND ad.step=jsonb_array_length(ai.steps_snapshot)-1 AND ad.context->>'role' IN('ADMIN','SERVICE_MANAGER','SALES','EXECUTIVE') AND ad.context->>'preparedHash'=encode(sha256(convert_to(current_order.approval_snapshot::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'AU-Freigabe ist nicht an den konkreten kommerziellen Prüfstand gebunden';END IF;
 IF current_order.approval_snapshot->>'id' IS DISTINCT FROM current_order.id::text OR current_order.approval_snapshot->>'organizationId' IS DISTINCT FROM current_order.organization_id::text OR current_order.approval_snapshot->'company'->>'id' IS DISTINCT FROM current_order.company_id::text OR current_order.approval_snapshot->'area'->>'id' IS DISTINCT FROM current_order.sales_area_id::text OR (current_order.approval_snapshot->>'dataRevision')::int IS DISTINCT FROM current_order.data_revision OR current_order.approval_snapshot->'header'->>'partnerId' IS DISTINCT FROM current_order.partner_id::text OR current_order.approval_snapshot->'header'->>'currency' IS DISTINCT FROM current_order.currency OR (current_order.approval_snapshot->'header'->>'pricingDate')::date IS DISTINCT FROM current_order.pricing_date OR current_order.approval_snapshot->'header'->>'customerReference' IS DISTINCT FROM current_order.customer_reference OR current_order.customer_reference='' OR current_order.requested_on IS NULL OR current_order.responsible_id IS NULL OR current_order.payment_term_id IS NULL OR current_order.shipping_term_id IS NULL OR current_order.incoterm_id IS NULL OR current_order.incoterm_place='' OR current_order.delivery_block IS NOT NULL OR current_order.billing_block IS NOT NULL THEN RAISE EXCEPTION 'AU-Herkunft, Vollständigkeit oder Datenrevision stimmt nicht';END IF;
 IF NOT EXISTS(SELECT 1 FROM sd_sales_areas a JOIN sd_org_units so ON so.tenant_id=a.tenant_id AND so.id=a.sales_org_id JOIN sd_org_units ch ON ch.tenant_id=a.tenant_id AND ch.id=a.channel_id JOIN sd_org_units di ON di.tenant_id=a.tenant_id AND di.id=a.division_id WHERE a.tenant_id=current_order.tenant_id AND a.id=current_order.sales_area_id AND a.active AND so.active AND ch.active AND di.active AND a.version=(current_order.approval_snapshot->'area'->>'version')::int AND so.version=(current_order.approval_snapshot->'area'->>'salesOrgVersion')::int AND ch.version=(current_order.approval_snapshot->'area'->>'channelVersion')::int AND di.version=(current_order.approval_snapshot->'area'->>'divisionVersion')::int) THEN RAISE EXCEPTION 'Aktiver gebundener Vertriebsbereich fehlt';END IF;
 IF (SELECT count(*) FROM sales_order_partners WHERE tenant_id=current_order.tenant_id AND order_id=current_order.id)<>4 OR jsonb_array_length(current_order.approval_snapshot->'partners')<>4 OR EXISTS(SELECT 1 FROM sales_order_partners r JOIN business_partners bp ON bp.tenant_id=r.tenant_id AND bp.id=r.partner_id JOIN partner_addresses pa ON pa.tenant_id=r.tenant_id AND pa.id=r.address_id WHERE r.tenant_id=current_order.tenant_id AND r.order_id=current_order.id AND (bp.status<>'ACTIVE' OR NOT pa.active OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(current_order.approval_snapshot->'partners') x WHERE x->>'role'=r.role AND x->>'partnerId'=r.partner_id::text AND x->'address'->>'id'=r.address_id::text AND (x->'address'->>'version')::int=pa.version AND (x->>'version')::int=bp.version))) THEN RAISE EXCEPTION 'Vollständige gebundene AU-Partner-/Adressrollen fehlen';END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(current_order.approval_snapshot->'items'))<>(SELECT count(*) FROM sales_order_items WHERE tenant_id=current_order.tenant_id AND order_id=current_order.id) OR NOT EXISTS(SELECT 1 FROM sales_order_items WHERE tenant_id=current_order.tenant_id AND order_id=current_order.id AND rejection_reason IS NULL) OR EXISTS(SELECT 1 FROM sales_order_items item JOIN products product ON product.tenant_id=item.tenant_id AND product.id=item.product_id WHERE item.tenant_id=current_order.tenant_id AND item.order_id=current_order.id AND (NOT EXISTS(SELECT 1 FROM jsonb_array_elements(current_order.approval_snapshot->'items') x WHERE x->>'id'=item.id::text AND x->>'productId'=item.product_id::text AND (x->>'quantity')::numeric=item.quantity AND x->'price'=item.price_snapshot AND x->'product'=item.product_snapshot AND (x->>'net')::numeric=item.net AND (x->>'tax')::numeric=item.tax AND (x->>'gross')::numeric=item.gross AND (x->>'rejectionReason') IS NOT DISTINCT FROM item.rejection_reason) OR (item.rejection_reason IS NULL AND (product.status<>'ACTIVE' OR item.cost_center='' OR item.cost_object='' OR item.delivery_block IS NOT NULL OR item.billing_block IS NOT NULL OR item.quantity<>(SELECT coalesce(sum(quantity),0) FROM sales_order_schedules WHERE tenant_id=item.tenant_id AND item_id=item.id))))) THEN RAISE EXCEPTION 'AU-Positionen, Preise oder Einteilungen passen nicht zum tatsächlichen Freigabestand';END IF;
 IF EXISTS((SELECT id,item_id,position,quantity,requested_on,confirmed_on FROM sales_order_schedules WHERE tenant_id=current_order.tenant_id AND order_id=current_order.id EXCEPT ALL SELECT x.id,x."itemId",x.position,x.quantity,x."requestedOn",x."confirmedOn" FROM jsonb_to_recordset(current_order.approval_snapshot->'schedules') AS x(id uuid,"itemId" uuid,position integer,quantity numeric,"requestedOn" date,"confirmedOn" date)) UNION ALL (SELECT x.id,x."itemId",x.position,x.quantity,x."requestedOn",x."confirmedOn" FROM jsonb_to_recordset(current_order.approval_snapshot->'schedules') AS x(id uuid,"itemId" uuid,position integer,quantity numeric,"requestedOn" date,"confirmedOn" date) EXCEPT ALL SELECT id,item_id,position,quantity,requested_on,confirmed_on FROM sales_order_schedules WHERE tenant_id=current_order.tenant_id AND order_id=current_order.id)) THEN RAISE EXCEPTION 'AU-Termineinteilungen stimmen nicht mit der unabhängigen Freigabe überein';END IF;
 RETURN NULL;
END$$;
CREATE CONSTRAINT TRIGGER sales_order_release_complete AFTER INSERT OR UPDATE ON sales_orders DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION sales_order_release_consistent();
-- One complete accepted commercial order may start one independently approved
-- execution order in this phase. Partial or replacement execution is separate.
ALTER TABLE service_orders ADD COLUMN source_sales_order_id uuid,ADD FOREIGN KEY(tenant_id,source_sales_order_id) REFERENCES sales_orders(tenant_id,id),ADD UNIQUE(tenant_id,source_sales_order_id);
ALTER TABLE service_order_items ADD COLUMN source_sales_item_id uuid,ADD FOREIGN KEY(tenant_id,source_sales_item_id) REFERENCES sales_order_items(tenant_id,id),ADD UNIQUE(tenant_id,source_sales_item_id);
CREATE FUNCTION sales_service_header_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE commercial sales_orders;org uuid;BEGIN
 IF TG_OP='UPDATE' AND NEW.source_sales_order_id IS DISTINCT FROM OLD.source_sales_order_id THEN RAISE EXCEPTION 'Kommerzielle AU-Herkunft des SA bleibt erhalten';END IF;
 IF NEW.source_sales_order_id IS NULL THEN RETURN NEW;END IF;
 SELECT * INTO STRICT commercial FROM sales_orders WHERE tenant_id=NEW.tenant_id AND id=NEW.source_sales_order_id;SELECT organization_id INTO STRICT org FROM documents WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 IF commercial.status<>'RELEASED' OR commercial.released_snapshot IS NULL OR commercial.organization_id<>org OR commercial.partner_id<>NEW.partner_id OR commercial.currency<>NEW.currency OR commercial.pricing_date<>NEW.pricing_date OR NEW.title<>commercial.title OR NEW.kind<>(CASE commercial.kind WHEN 'PROJECT' THEN 'PROJECT' WHEN 'REPAIR' THEN 'REPAIR' ELSE 'PAID' END) OR NEW.source_ticket_id IS NULL THEN RAISE EXCEPTION 'SA muss zum tatsächlich freigegebenen AU und technischen Ursprung gehören';END IF;
 IF NOT EXISTS(SELECT 1 FROM tickets t JOIN documents d ON d.tenant_id=t.tenant_id AND d.id=t.id WHERE t.tenant_id=NEW.tenant_id AND t.id=NEW.source_ticket_id AND t.case_id=NEW.case_id AND t.partner_id=NEW.partner_id AND d.organization_id=org AND t.type NOT IN('WARRANTY','INTERNAL')) THEN RAISE EXCEPTION 'Technischer Ursprung erlaubt diesen kostenpflichtigen AU-Folgeauftrag nicht';END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER sales_service_header_source BEFORE INSERT OR UPDATE ON service_orders FOR EACH ROW EXECUTE FUNCTION sales_service_header_guard();
CREATE FUNCTION sales_service_item_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE execution service_orders;commercial sales_order_items;BEGIN
 IF TG_OP='DELETE' THEN SELECT * INTO STRICT execution FROM service_orders WHERE tenant_id=OLD.tenant_id AND id=OLD.order_id;IF execution.source_sales_order_id IS NOT NULL THEN RAISE EXCEPTION 'An AU gebundene SA-Position benötigt gesonderten Änderungsprozess';END IF;RETURN OLD;END IF;
 SELECT * INTO STRICT execution FROM service_orders WHERE tenant_id=NEW.tenant_id AND id=NEW.order_id;
 IF execution.source_sales_order_id IS NULL THEN IF NEW.source_sales_item_id IS NOT NULL THEN RAISE EXCEPTION 'AU-Position benötigt passenden AU-Folgeauftrag';END IF;RETURN NEW;END IF;
 IF NEW.source_sales_item_id IS NULL THEN RAISE EXCEPTION 'Freie Zusatzposition im gebundenen AU-Folgeauftrag ist nicht zulässig';END IF;
 SELECT * INTO STRICT commercial FROM sales_order_items WHERE tenant_id=NEW.tenant_id AND id=NEW.source_sales_item_id;
 IF commercial.order_id<>execution.source_sales_order_id OR commercial.rejection_reason IS NOT NULL OR (commercial.position,commercial.product_id,commercial.description,commercial.quantity,commercial.unit,commercial.billing_rule,commercial.cost_center,commercial.cost_object,commercial.net,commercial.tax,commercial.gross) IS DISTINCT FROM (NEW.position,NEW.product_id,NEW.description,NEW.quantity,NEW.unit,NEW.billing_rule,NEW.cost_center,NEW.cost_object,NEW.net,NEW.tax,NEW.gross) OR NEW.required_on IS DISTINCT FROM coalesce((SELECT min(sc.requested_on) FROM sales_order_schedules sc WHERE sc.tenant_id=NEW.tenant_id AND sc.item_id=commercial.id),commercial.requested_on,(SELECT so.requested_on FROM sales_orders so WHERE so.tenant_id=NEW.tenant_id AND so.id=execution.source_sales_order_id)) OR (NEW.price_snapshot-'sourceSalesOrder'-'currency'-'date') IS DISTINCT FROM commercial.price_snapshot OR NEW.price_snapshot->'sourceSalesOrder'->>'id' IS DISTINCT FROM execution.source_sales_order_id::text OR NEW.price_snapshot->'sourceSalesOrder'->>'itemId' IS DISTINCT FROM commercial.id::text THEN RAISE EXCEPTION 'SA-Position muss ursprüngliche akzeptierte AU-Mengen, Preise und Kontierung übernehmen';END IF;
 IF TG_OP='UPDATE' AND NEW.source_sales_item_id IS DISTINCT FROM OLD.source_sales_item_id THEN RAISE EXCEPTION 'AU-Positionsherkunft bleibt unveränderlich';END IF;RETURN NEW;
END$$;
CREATE TRIGGER sales_service_item_source BEFORE INSERT OR UPDATE OR DELETE ON service_order_items FOR EACH ROW EXECUTE FUNCTION sales_service_item_guard();
CREATE FUNCTION sales_service_complete() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE execution service_orders;BEGIN
 IF TG_TABLE_NAME='service_orders' THEN SELECT * INTO STRICT execution FROM service_orders WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
 ELSE SELECT * INTO STRICT execution FROM service_orders WHERE tenant_id=NEW.tenant_id AND id=NEW.order_id;END IF;
 IF execution.source_sales_order_id IS NULL THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM sales_order_items i WHERE i.tenant_id=execution.tenant_id AND i.order_id=execution.source_sales_order_id AND i.rejection_reason IS NULL AND NOT EXISTS(SELECT 1 FROM service_order_items e WHERE e.tenant_id=execution.tenant_id AND e.order_id=execution.id AND e.source_sales_item_id=i.id)) THEN RAISE EXCEPTION 'AU-Folgeauftrag muss alle tatsächlich akzeptierten Positionen genau einmal übernehmen';END IF;
 RETURN NULL;
END$$;
CREATE CONSTRAINT TRIGGER sales_service_complete_header AFTER INSERT OR UPDATE ON service_orders DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION sales_service_complete();
CREATE CONSTRAINT TRIGGER sales_service_complete_item AFTER INSERT OR UPDATE ON service_order_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION sales_service_complete();
ALTER TABLE goods_issues ADD COLUMN receiver_snapshot jsonb;
CREATE FUNCTION sales_delivery_source_consistent() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE issue goods_issues;execution service_orders;commercial sales_orders;party jsonb;expected_receiver jsonb;BEGIN
 SELECT * INTO STRICT issue FROM goods_issues WHERE tenant_id=NEW.tenant_id AND id=NEW.id;SELECT * INTO STRICT execution FROM service_orders WHERE tenant_id=issue.tenant_id AND id=issue.order_id;
 IF execution.source_sales_order_id IS NULL THEN IF issue.receiver_snapshot IS NOT NULL THEN RAISE EXCEPTION 'AU-Empfängersnapshot benötigt tatsächlichen AU-Folgeauftrag';END IF;RETURN NULL;END IF;
 SELECT * INTO STRICT commercial FROM sales_orders WHERE tenant_id=issue.tenant_id AND id=execution.source_sales_order_id;
 IF issue.movement_type='ISSUE' THEN
  SELECT x INTO party FROM jsonb_array_elements(commercial.released_snapshot->'commercial'->'partners') x WHERE x->>'role'='SHIP_TO';
  expected_receiver:=party||jsonb_build_object('salesOrderId',commercial.id,'salesOrderNumber',(SELECT number FROM documents WHERE tenant_id=commercial.tenant_id AND id=commercial.id));
 ELSE SELECT receiver_snapshot INTO expected_receiver FROM goods_issues WHERE tenant_id=issue.tenant_id AND id=issue.reverses_id;END IF;
 IF expected_receiver IS NULL OR issue.receiver_snapshot IS DISTINCT FROM expected_receiver THEN RAISE EXCEPTION 'Auslieferung muss den tatsächlich freigegebenen AU-Empfänger bzw. Originalempfänger erhalten';END IF;RETURN NULL;
END$$;
CREATE CONSTRAINT TRIGGER sales_delivery_source_complete AFTER INSERT OR UPDATE ON goods_issues DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION sales_delivery_source_consistent();
CREATE FUNCTION sales_invoice_source_consistent() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE execution service_orders;commercial sales_orders;buyer jsonb;payer jsonb;payment jsonb;BEGIN
 SELECT * INTO STRICT execution FROM service_orders WHERE tenant_id=NEW.tenant_id AND id=NEW.order_id;IF execution.source_sales_order_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO STRICT commercial FROM sales_orders WHERE tenant_id=NEW.tenant_id AND id=execution.source_sales_order_id;
 SELECT x INTO buyer FROM jsonb_array_elements(commercial.released_snapshot->'commercial'->'partners') x WHERE x->>'role'='BILL_TO';SELECT x INTO payer FROM jsonb_array_elements(commercial.released_snapshot->'commercial'->'partners') x WHERE x->>'role'='PAYER';SELECT x INTO payment FROM jsonb_array_elements(commercial.released_snapshot->'commercial'->'terms') x WHERE x->>'kind'='PAYMENT';
 IF buyer IS NULL OR payer IS NULL OR payment IS NULL OR (buyer->>'partnerId')::uuid IS DISTINCT FROM NEW.partner_id OR (payer->>'partnerId')::uuid IS DISTINCT FROM NEW.partner_id OR NEW.snapshot->>'salesOrderNumber' IS DISTINCT FROM (SELECT number FROM documents WHERE tenant_id=NEW.tenant_id AND id=commercial.id) OR NEW.snapshot->>'customerOrderReference' IS DISTINCT FROM commercial.customer_reference OR NEW.snapshot->'buyer'->>'name' IS DISTINCT FROM buyer->>'name' OR NEW.snapshot->'buyer'->>'street' IS DISTINCT FROM buyer->'address'->>'street' OR NEW.snapshot->'buyer'->>'postalCode' IS DISTINCT FROM buyer->'address'->>'postalCode' OR NEW.snapshot->'buyer'->>'city' IS DISTINCT FROM buyer->'address'->>'city' OR NEW.snapshot->'buyer'->>'country' IS DISTINCT FROM buyer->'address'->>'country' OR (NEW.snapshot->>'dueDate')::date IS DISTINCT FROM (NEW.snapshot->>'date')::date+(payment->>'netDays')::int THEN RAISE EXCEPTION 'Faktura muss freigegebene AU-Partner-, Adress-, Referenz- und Zahlungsbedingungen erhalten';END IF;RETURN NULL;
END$$;
CREATE CONSTRAINT TRIGGER sales_invoice_source_complete AFTER INSERT ON invoices DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION sales_invoice_source_consistent();
